parameters.jsCode:
// Plan domain lookups
// RDAP needs the registered domain, which is not always the last two labels
// (shop.firma.com.pl -> firma.com.pl). Without a public-suffix list, RDAP is
// asked for two candidates - the last three and the last two labels - and
// "Data reduction - RDAP" keeps the longest one the registry knows.
// Mode: Run Once for All Items (emits one item per candidate).

const claim = $('Claim next verdict').first().json;
const labels = String(claim.fqdn).toLowerCase().replace(/\.$/, '').split('.').filter(Boolean);
const candidates = [];
if (labels.length >= 3) candidates.push(labels.slice(-3).join('.'));
if (labels.length >= 2) candidates.push(labels.slice(-2).join('.'));
return candidates.map((domain) => ({ json: { domain } }));

// Data reduction - RDAP
// Keeps the longest candidate the registry answered for (the registered
// domain) and reduces the RDAP record (RFC 9083) to what an analyst needs:
// registration date and age, registrar, status flags, nameservers.
// Not every TLD offers RDAP: no answer is recorded as status "no_data".
// Mode: Run Once for All Items.

const claim = $('Claim next verdict').first().json;
const candidates = $('Plan domain lookups').all().map((i) => i.json.domain);
const answers = $input.all().map((item, i) => ({ domain: candidates[i], res: item.json }));

const parsed = answers
  .map((a) => {
    let body = a.res?.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
    return { domain: a.domain, status: a.res?.statusCode, body };
  })
  .filter((a) => a.status === 200 && a.body && a.body.objectClassName === 'domain');
parsed.sort((a, b) => b.domain.split('.').length - a.domain.split('.').length);
const best = parsed[0];

let domain;
let raw = null;
if (!best) {
  const codes = answers.map((a) => a.res?.statusCode ?? (a.res?.error ? 'error' : 'n/a'));
  domain = {
    status: codes.every((c) => c === 404) ? 'no_data' : 'error',
    registrable_domain: candidates[candidates.length - 1] || null,
    message: `RDAP answered ${codes.join(', ')}`,
  };
} else {
  const b = best.body;
  const event = (action) => (Array.isArray(b.events) ? b.events : []).find((e) => e.eventAction === action)?.eventDate || null;
  const vcardName = (ent) => {
    const props = Array.isArray(ent?.vcardArray?.[1]) ? ent.vcardArray[1] : [];
    const fn = props.find((p) => Array.isArray(p) && p[0] === 'fn');
    return fn ? String(fn[3] || '').trim() : '';
  };
  // Registrar can be nested one level down (registry -> registrar entity).
  const entities = (Array.isArray(b.entities) ? b.entities : [])
    .flatMap((e) => [e, ...(Array.isArray(e.entities) ? e.entities : [])]);
  const registrar = entities.find((e) => Array.isArray(e.roles) && e.roles.includes('registrar'));
  const registered = event('registration');
  const ageDays = registered && !Number.isNaN(Date.parse(registered))
    ? Math.floor((Date.now() - Date.parse(registered)) / 86400000) : null;
  domain = {
    status: 'ok',
    registrable_domain: String(b.ldhName || best.domain).toLowerCase(),
    registered_at: registered,
    age_days: ageDays,
    expires_at: event('expiration'),
    last_changed_at: event('last changed'),
    registrar: (vcardName(registrar) || null)?.slice(0, 200) ?? null,
    status_flags: (Array.isArray(b.status) ? b.status : []).map(String).slice(0, 10),
    nameservers: (Array.isArray(b.nameservers) ? b.nameservers : [])
      .map((n) => String(n.ldhName || '').toLowerCase()).filter(Boolean).slice(0, 8),
    dnssec: typeof b.secureDNS?.delegationSigned === 'boolean' ? b.secureDNS.delegationSigned : null,
  };
  raw = { source: 'RDAP', resource: domain.registrable_domain, payload: b };
}
domain.shared_platform = claim.shared_platform === true;

return [{ json: { domain, raw } }];

// Data reduction - domain
// Certificate history from crt.sh (Certificate Transparency logs): how many
// certificates, when the first and the latest were issued, by whom, and the
// subdomains they name. crt.sh is often slow or down: a failure is recorded
// as status "error" and the run goes on. Only the reduced facts are kept.
// Mode: Run Once for Each Item.

const { domain, raw } = $('Data reduction - RDAP').first().json;
const res = $json;

let certificates;
let rows = null;
if (res?.statusCode === 200) {
  try { rows = typeof res.body === 'string' ? JSON.parse(res.body) : res.body; } catch (e) { rows = null; }
}
if (!Array.isArray(rows)) {
  certificates = { status: 'error', error: res?.statusCode ? `HTTP ${res.statusCode}` : String(res?.error?.message || res?.error || 'request failed') };
} else if (rows.length === 0) {
  certificates = { status: 'no_data' };
} else {
  const time = (v) => { const t = Date.parse(String(v || '').replace(' ', 'T') + (/[zZ]|[+-]\d\d:?\d\d$/.test(String(v)) ? '' : 'Z')); return Number.isNaN(t) ? null : t; };
  const issued = rows.map((r) => time(r.not_before) ?? time(r.entry_timestamp)).filter((t) => t !== null);
  const issuerOrg = (n) => (String(n || '').match(/O=("?)([^,"]+)\1/) || [])[2] || String(n || '').slice(0, 60);
  const issuers = {};
  rows.forEach((r) => { const k = issuerOrg(r.issuer_name); issuers[k] = (issuers[k] || 0) + 1; });
  const names = new Set();
  rows.forEach((r) => String(r.name_value || '').split('\n').forEach((n) => { n = n.trim().toLowerCase(); if (n) names.add(n); }));
  const iso = (t) => (t === null ? null : new Date(t).toISOString());
  certificates = {
    status: 'ok',
    count: rows.length,
    first_seen: iso(issued.length ? Math.min(...issued) : null),
    latest: iso(issued.length ? Math.max(...issued) : null),
    first_seen_days_ago: issued.length ? Math.floor((Date.now() - Math.min(...issued)) / 86400000) : null,
    issuers: Object.entries(issuers).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([name, n]) => ({ name, certificates: n })),
    names_seen: names.size,
    name_sample: [...names].sort().slice(0, 20),
  };
}

return { json: { domain, certificates, raw: raw ? [raw] : [] } };

// Plan scan
// Reuses the newest urlscan.io scan of exactly this domain when one exists
// within recon_reuse_days; otherwise asks for a new scan. Without a urlscan
// key the page is skipped - the analyst still gets the domain context.
// Mode: Run Once for Each Item.

const claim = $('Claim next verdict').first().json;
const vault = $('urlscan.io API TOKEN').first().json;
const res = $json;

if (vault.error || !vault.data?.token) {
  return { json: { action: 'skip', failure: { page_status: 'not_scanned', mode: null, uuid: null,
    message: 'No urlscan.io key in Vault (cyber-sentinel/api-keys/urlscanio/api-key, vault_urlscanio_api_key, playbook 06.1).' } } };
}

let body = res?.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const fqdn = String(claim.fqdn).toLowerCase();
const scans = (res?.statusCode === 200 && Array.isArray(body?.results) ? body.results : [])
  .filter((r) => String(r?.page?.domain || '').toLowerCase() === fqdn && (r._id || r.task?.uuid))
  .sort((a, b) => String(b?.task?.time || '').localeCompare(String(a?.task?.time || '')));

if (scans.length > 0) {
  return { json: { action: 'reuse', uuid: scans[0]._id || scans[0].task.uuid, mode: 'reused' } };
}
return { json: { action: 'submit', search_status: res?.statusCode ?? null } };

