parameters.jsCode:
// Accept submission
// 200 -> scan queued at urlscan.io (counts against recon_daily_limit).
// 400 "DNS Error" / "could not resolve" -> the domain no longer resolves
//     publicly: page_status 'unreachable' (useful: the site is gone).
// Anything else (quota 429, auth 401, blocked domain, ...) -> 'error'.
// Mode: Run Once for Each Item.

const settings = $('Load recon configuration').first().json.settings;
const res = $json;
let body = res?.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { message: body.slice(0, 200) }; } }
body = body || {};

if (res?.statusCode === 200 && body.uuid) {
  return { json: { ok: true, uuid: body.uuid, mode: 'submitted',
    visibility: body.visibility || (Number(settings.recon_private_scans) === 1 ? 'private' : 'unlisted') } };
}

const detail = [body.message, body.description].filter(Boolean).join(' - ').slice(0, 300)
  || String(res?.error?.message || res?.error || 'no response').slice(0, 300);
const unreachable = res?.statusCode === 400 && /dns|resolve/i.test(detail);
return { json: { ok: false, failure: {
  page_status: unreachable ? 'unreachable' : 'error',
  mode: null,
  uuid: null,
  message: `urlscan.io submit HTTP ${res?.statusCode ?? 'n/a'}: ${detail}`,
} } };

// Check scan result
// 200 -> ready. 404 -> scan still running: wait 10 s and poll again (this
// node runs once per poll; $runIndex counts the polls). 410 -> scan deleted.
// Gives up after MAX_POLLS (~30 s + 6 x 10 s).
// Mode: Run Once for Each Item.

const MAX_POLLS = 6;
const planned = $('Plan scan').first().json;
const submitted = $('Accept submission').isExecuted ? $('Accept submission').first().json : null;
const scan = planned.action === 'reuse' ? planned : submitted;
const res = $json;
const attempt = $runIndex + 1;

if (res?.statusCode === 200 && res.body && typeof res.body === 'object') {
  return { json: { state: 'ready', uuid: scan.uuid, mode: scan.mode, visibility: scan.visibility || null, result: res.body } };
}
if (res?.statusCode === 404 && attempt < MAX_POLLS) {
  return { json: { state: 'pending', uuid: scan.uuid, attempt } };
}
const why = res?.statusCode === 404 ? `no result after ${attempt} polls`
  : res?.statusCode === 410 ? 'scan was deleted at urlscan.io'
  : `HTTP ${res?.statusCode ?? 'n/a'} ${String(res?.error?.message || res?.error || '').slice(0, 200)}`;
return { json: { state: 'failed', failure: { page_status: 'error', mode: scan.mode, uuid: scan.uuid,
  message: `urlscan.io result ${scan.uuid}: ${why}` } } };

// Keep scan result
// Runs once, after the last poll: later nodes read the scan from here
// (the polling nodes above may have run several times).
// Mode: Run Once for Each Item.

return { json: $json };

// Data reduction - page
// Turns the urlscan.io result (often several MB) and the page DOM into a
// compact fact sheet. The page is attacker-controlled: its text is only ever
// passed on as data, URLs are defanged, and everything is length-capped.
// Mode: Run Once for Each Item.

const claim = $('Claim next verdict').first().json;
const kept = $('Keep scan result').first().json;
const r = kept.result || {};
const domRes = $json;
const fqdn = String(claim.fqdn).toLowerCase();

const defang = (url) => (url ? String(url).replace(/^http/i, 'hxxp').replace(/\./g, '[.]') : null);
const cut = (s, n) => (s == null ? null : String(s).replace(/\s+/g, ' ').trim().slice(0, n));
const arr = (a, n) => (Array.isArray(a) ? a.slice(0, n) : []);
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));

function decodeEntities(s) {
  return s.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (m, d) => { const c = Number(d); return c > 0 && c < 0x110000 ? String.fromCodePoint(c) : ' '; })
    .replace(/&#x([0-9a-f]+);/gi, (m, h) => { const c = parseInt(h, 16); return c > 0 && c < 0x110000 ? String.fromCodePoint(c) : ' '; });
}
function hostOf(action, base) {
  try { return new URL(action || '', base).hostname.toLowerCase(); } catch (e) { return null; }
}

const MAX_HTML = 2_000_000;   // never scan more than ~2 MB of markup
const MAX_TEXT = 6000;        // characters of page text sent to the model
let dom = { dom_status: 'missing', text: '', text_truncated: false, forms: 0, password_field: false,
  card_field: false, form_targets: [], external_form_targets: [] };

if (domRes?.statusCode === 200 && typeof domRes.body === 'string' && domRes.body.length > 0) {
  // Comments and script/style bodies first, so markup inside them
  // ("<form ...>" in a JS string) is not counted as a real form.
  const html = domRes.body.slice(0, MAX_HTML)
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|template|iframe|object)\b[\s\S]*?<\/\1\s*>/gi, ' ');
  const forms = html.match(/<form\b[^>]*>/gi) || [];
  const baseUrl = r.page?.url || `http://${fqdn}/`;
  const targets = [...new Set(forms
    .map((f) => (f.match(/\baction\s*=\s*["']?([^"'\s>]*)/i) || [])[1])
    .map((a) => hostOf(a, baseUrl))
    .filter(Boolean))];
  const finalHost = hostOf(baseUrl, baseUrl);
  const text = decodeEntities(html
    .replace(/<(br|p|div|li|tr|h[1-6]|section|article|header|footer|form|label|button|option)\b[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t\f\v\r]+/g, ' ')
    .replace(/\n\s*/g, '\n')
    .replace(/\n{2,}/g, '\n')
    .trim();
  dom = {
    dom_status: 'ok',
    text: text.slice(0, MAX_TEXT),
    text_truncated: text.length > MAX_TEXT,
    forms: forms.length,
    password_field: /<input\b[^>]*\btype\s*=\s*["']?password\b/i.test(html),
    card_field: /\bautocomplete\s*=\s*["']?cc-(number|csc|exp)|<input\b[^>]*\bname\s*=\s*["'][^"']*(card.?num|cvv|cvc)/i.test(html),
    form_targets: targets.slice(0, 10),
    external_form_targets: targets.filter((h) => h !== finalHost).slice(0, 10),
  };
} else if (domRes?.statusCode && domRes.statusCode !== 200) {
  dom.dom_status = `http_${domRes.statusCode}`;
}

const overall = r.verdicts?.overall || {};
const us = r.verdicts?.urlscan || {};
const brands = [...new Set([
  ...arr(overall.brands, 10).map((b) => (typeof b === 'string' ? b : b?.name || b?.key)),
  ...arr(us.brands, 10).map((b) => (typeof b === 'string' ? b : b?.name || b?.key)),
].filter(Boolean))].slice(0, 10);
const finalDomain = (r.page?.domain || '').toLowerCase() || null;

// TLS certificates the page used (urlscan lists.certificates: validFrom /
// validTo are Unix seconds). The final domain's certificate comes first.
const toIso = (v) => { const n = Number(v); const t = Number.isFinite(n) && n > 0 ? n * 1000 : Date.parse(v); return Number.isNaN(t) || !t ? null : new Date(t).toISOString(); };
const certs = arr(r.lists?.certificates, 50).map((c) => {
  const from = toIso(c.validFrom);
  return {
    subject: cut(c.subjectName, 120),
    issuer: cut(c.issuer, 120),
    valid_from: from,
    valid_to: toIso(c.validTo),
    age_days: from ? Math.floor((Date.now() - Date.parse(from)) / 86400000) : null,
  };
}).filter((c) => c.subject);
const ownCert = (c) => { const s = String(c.subject).toLowerCase().replace(/^\*\./, ''); return finalDomain && (finalDomain === s || finalDomain.endsWith(`.${s}`)); };
certs.sort((a, b) => ownCert(b) - ownCert(a));

const page = {
  status: 'scanned',
  mode: kept.mode,
  scanned_at: r.task?.time || null,
  submitted_url: defang(r.task?.url),
  final_url: defang(r.page?.url),
  final_domain: finalDomain,
  redirected_to_other_domain: Boolean(finalDomain && finalDomain !== fqdn),
  http_status: num(r.page?.status),
  title: cut(r.page?.title, 200),
  mime_type: cut(r.page?.mimeType, 80),
  server: cut(r.page?.server, 100),
  hosting: { ip: r.page?.ip || null, as_owner: cut(r.page?.asnname, 100), country: r.page?.country || null },
  tls: { issuer: cut(r.page?.tlsIssuer, 100), age_days: num(r.page?.tlsAgeDays), valid_days: num(r.page?.tlsValidDays) },
  urlscan: {
    score: num(overall.score ?? us.score),
    malicious: typeof overall.malicious === 'boolean' ? overall.malicious : (typeof us.malicious === 'boolean' ? us.malicious : null),
    categories: [...new Set([...arr(overall.categories, 10), ...arr(us.categories, 10)].map(String))].slice(0, 10),
    brands,
  },
  contacted_domains: arr(r.lists?.domains, 200).map((d) => String(d).toLowerCase()).filter((d) => d !== fqdn).slice(0, 25),
  link_domains: arr(r.lists?.linkDomains, 100).map((d) => String(d).toLowerCase()).filter((d) => d !== fqdn).slice(0, 15),
  requests: Array.isArray(r.data?.requests) ? r.data.requests.length : null,
  certificates: certs.slice(0, 5),
  downloads: arr(r.meta?.processors?.download?.data, 5).map((d) => ({
    filename: cut(d.filename, 120), mime_type: cut(d.mimeType, 80), size: num(d.filesize), sha256: d.sha256 || null,
  })),
  ...dom,
};

return {
  json: {
    page,
    scan: {
      uuid: kept.uuid,
      mode: kept.mode,
      visibility: kept.visibility || r.task?.visibility || null,
      scan_time: r.task?.time || null,
      report_url: `https://urlscan.io/result/${kept.uuid}/`,
      screenshot_url: `https://urlscan.io/screenshots/${kept.uuid}.png`,
    },
    // Trimmed raw payload for cyber_sentinel.threat_data_raw (no request log, no DOM).
    raw: {
      source: 'urlscan.io',
      resource: fqdn,
      payload: {
        task: r.task || null,
        page: r.page || null,
        verdicts: r.verdicts || null,
        stats: r.stats || null,
        lists: Object.fromEntries(Object.entries(r.lists || {}).map(([k, v]) => [k, arr(v, 100)])),
        downloads: arr(r.meta?.processors?.download?.data, 20),
      },
    },
  },
};

// No page scan
// The page could not be scanned (no urlscan key, submission refused, domain
// does not resolve, no result in time). The analyst still re-assesses the
// verdict with the domain and certificate context.
// Mode: Run Once for Each Item.

const f = $json.failure || { page_status: 'error', message: 'unknown failure' };
return {
  json: {
    page: { status: f.page_status, message: f.message },
    scan: f.uuid ? { uuid: f.uuid, mode: f.mode, report_url: `https://urlscan.io/result/${f.uuid}/` } : null,
    raw: null,
  },
};

// Build recon prompt
// System message = active row of cyber_sentinel_ai.recon_prompt_templates
// with [[THREAT_SCALE]] and [[MAX_DEVIATION]] (= recon_max_deviation)
// resolved. User message = the current verdict and everything Deep Recon
// collected, as JSON. Page text is untrusted: data only, no tools.
// Mode: Run Once for Each Item.

const config = $('Load recon configuration').first().json;
const claim = $('Claim next verdict').first().json;
const dom = $('Data reduction - domain').first().json;
const { page, scan, raw } = $json;

if (!config.system_prompt) {
  throw new Error('No active recon prompt: set is_active = true on one row of cyber_sentinel_ai.recon_prompt_templates');
}
const maxDev = Math.max(0, Math.trunc(Number(config.settings.recon_max_deviation) || 0));
const systemMessage = config.system_prompt
  .replaceAll('[[THREAT_SCALE]]', config.threat_scale || '')
  .replaceAll('[[MAX_DEVIATION]]', String(maxDev));

const userMessage = {
  verdict: {
    domain: claim.fqdn,
    ip: claim.observable_ip,
    final_score: claim.original_score,
    label: claim.original_label,
    summary: claim.original_summary,
    rule_score: claim.rule_score,
    virustotal_malicious: claim.vt_malicious,
    primary_evidence: claim.primary_evidence,
    supporting_context: claim.supporting_context,
    ai_deviation_reason: claim.deviation_reason || null,
    shodan: claim.shodan || null,
    urlscan_search: claim.urlscan_search || null,
    analysed_at: claim.analyzed_at,
  },
  domain: dom.domain,
  certificates: dom.certificates,
  page,
};

return {
  json: {
    system_message: systemMessage,
    user_message: JSON.stringify(userMessage, null, 2),
    max_deviation: maxDev,
    // Everything "Save recon result" stores, apart from the AI answer.
    recon: {
      recon_id: claim.recon_id,
      analysis_result_id: claim.analysis_result_id,
      fqdn: claim.fqdn,
      original_score: claim.original_score,
      registrable_domain: dom.domain.registrable_domain || null,
      domain_registered_at: dom.domain.registered_at || null,
      domain_age_days: dom.domain.age_days ?? null,
      registrar: dom.domain.registrar || null,
      cert_first_seen: dom.certificates.first_seen || null,
      cert_count: dom.certificates.count ?? null,
      page_status: page.status,
      mode: scan?.mode || null,
      visibility: scan?.visibility || null,
      scan_uuid: scan?.uuid || null,
      scan_time: scan?.scan_time || null,
      report_url: scan?.report_url || null,
      screenshot_url: page.status === 'scanned' ? scan?.screenshot_url || null : null,
      final_url: page.final_url || null,
      page_title: page.title || null,
      urlscan_score: page.urlscan?.score ?? null,
      urlscan_malicious: page.urlscan?.malicious ?? null,
      message: page.status === 'scanned' ? null : page.message || null,
      facts: {
        domain: dom.domain,
        certificates: dom.certificates,
        same_ip_sites: claim.urlscan_search?.same_ip || null,
        page: { ...page, text: undefined, text_excerpt: page.text ? page.text.slice(0, 2000) : undefined },
      },
      raw: [...dom.raw, ...(raw ? [raw] : [])],
    },
  },
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "page_type": {
      "type": "string",
      "enum": [
        "phishing",
        "scam",
        "malware_delivery",
        "fake_update",
        "parked",
        "legitimate",
        "error_or_empty",
        "unknown"
      ]
    },
    "impersonated_brand": {
      "type": "string",
      "description": "Brand name or empty string"
    },
    "credential_harvesting": {
      "type": "boolean"
    },
    "supports_verdict": {
      "type": "string",
      "enum": [
        "confirms",
        "contradicts",
        "inconclusive"
      ]
    },
    "confidence": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high"
      ]
    },
    "proposed_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "score_reason": {
      "type": "string",
      "description": "One sentence"
    },
    "indicators": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Up to 6 short English phrases"
    },
    "summary_en": {
      "type": "string",
      "description": "One or two English sentences"
    },
    "analysis_pl": {
      "type": "string",
      "description": "2-4 sentences in Polish for the analyst"
    }
  },
  "required": [
    "page_type",
    "impersonated_brand",
    "credential_harvesting",
    "supports_verdict",
    "confidence",
    "proposed_score",
