// Parse recon analyst output
// Validates the structured answer and enforces the limit itself: the
// proposed score stays within recon_max_deviation of the verdict, whatever
// the model says. If the model failed or answered outside the schema, the
// collected facts are still saved with ai_status = 'failed' and no score.
// Mode: Run Once for Each Item.

// Keep in sync with the model selected in the "Google Gemini Chat Model" node.
const AI_MODEL = 'gemini-3.1-flash-lite';

const config = $('Load recon configuration').first().json;
const built = $('Build recon prompt').first().json;
const recon = built.recon;
const ai = $json; // { output: {...} } | { text: '...' } | { error: ... }

const PAGE_TYPES = ['phishing', 'scam', 'malware_delivery', 'fake_update', 'parked', 'legitimate', 'error_or_empty', 'unknown'];
const SUPPORTS = ['confirms', 'contradicts', 'inconclusive'];
const CONFIDENCE = ['low', 'medium', 'high'];

function text(value, field, max, required = true) {
  if (typeof value !== 'string') throw new Error(`"${field}" is not a string`);
  const clean = value.replace(/\s+/g, ' ').trim();
  if (required && !clean) throw new Error(`"${field}" is empty`);
  return clean.slice(0, max);
}
function oneOf(value, field, allowed) {
  const v = String(value ?? '').trim().toLowerCase();
  if (!allowed.includes(v)) throw new Error(`"${field}" must be one of ${allowed.join('/')}, got ${JSON.stringify(value)}`);
  return v;
}

let result = null;
let aiError = null;
try {
  if (ai.error) throw new Error(`Recon analyst failed: ${typeof ai.error === 'string' ? ai.error : ai.error.message || JSON.stringify(ai.error)}`);
  // Basic LLM Chain + Structured Output Parser returns { output: {...} };
  // accept a bare object or a JSON string too.
  let out = ai.output ?? ai.text ?? ai.response?.text ?? ('page_type' in ai ? ai : undefined);
  if (typeof out === 'string') {
    out = JSON.parse(out.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  }
  if (out && typeof out === 'object' && out.output && typeof out.output === 'object') out = out.output;
  if (!out || typeof out !== 'object') throw new Error('Recon analyst returned no structured output');
  if (typeof out.credential_harvesting !== 'boolean') throw new Error('"credential_harvesting" is not a boolean');
  const proposed = Number(out.proposed_score);
  if (!Number.isInteger(proposed)) throw new Error(`"proposed_score" is not an integer: ${JSON.stringify(out.proposed_score)}`);

  const original = Number(recon.original_score);
  const maxDev = Number(built.max_deviation);
  const clamped = Math.min(5, Math.max(1, Math.min(original + maxDev, Math.max(original - maxDev, proposed))));
  let reason = text(out.score_reason, 'score_reason', 500);
  if (clamped !== proposed) {
    reason = `${reason} (model proposed ${proposed}, limited to ${clamped} by recon_max_deviation = ${maxDev})`;
  }
  result = {
    page_type: oneOf(out.page_type, 'page_type', PAGE_TYPES),
    impersonated_brand: text(out.impersonated_brand ?? '', 'impersonated_brand', 100, false) || null,
    credential_harvesting: out.credential_harvesting,
    supports_verdict: oneOf(out.supports_verdict, 'supports_verdict', SUPPORTS),
    confidence: oneOf(out.confidence, 'confidence', CONFIDENCE),
    proposed_score: clamped,
    score_reason: reason,
    indicators: (Array.isArray(out.indicators) ? out.indicators : [])
      .filter((s) => typeof s === 'string' && s.trim())
      .slice(0, 6)
      .map((s) => s.replace(/\s+/g, ' ').trim().slice(0, 150)),
    summary_en: text(out.summary_en, 'summary_en', 1000),
    analysis_pl: text(out.analysis_pl, 'analysis_pl', 1500),
  };
} catch (e) {
  aiError = String(e.message).slice(0, 500);
}

return {
  json: {
    recon: {
      ...recon,
      ...(result || {}),
      ai_status: result ? 'ok' : 'failed',
      ai_error: aiError,
      ai_model: AI_MODEL,
      prompt_version: config.prompt_version,
    },
  },
};

// Build recon e-mail
// Sent when Deep Recon proposes a different score than the verdict. Every
// dynamic value is HTML-escaped: domains, page titles and AI text are
// untrusted input. Links point only to urlscan.io.
// Mode: Run Once for Each Item.

const r = $('Parse recon analyst output').first().json.recon;
const levels = $('Load recon configuration').first().json.threat_levels || {};
const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const link = (url, label) => (typeof url === 'string' && url.startsWith('https://urlscan.io/')
  ? `<a style="color:#90caf9;" href="${esc(url)}">${esc(label)}</a>` : '');

const up = r.proposed_score > r.original_score;
const theme = up
  ? { label: '🔺 SCORE RAISED', accent: '#f44336', text: '#ff5252', header: '#3a1f1f' }
  : { label: '🔻 SCORE LOWERED', accent: '#4caf50', text: '#81c784', header: '#1b3320' };
const level = levels[r.proposed_score] || {};

const box = (title, body) => (body
  ? `<p style="margin:14px 0 4px;color:#888;font-size:12px;text-transform:uppercase;">${title}</p>
     <div style="background:#252525;padding:12px;border-radius:4px;font-size:14px;line-height:1.6;">${body}</div>`
  : '');
const f = r.facts || {};
const d = f.domain || {};
const c = f.certificates || {};
const p = f.page || {};
const pc = Array.isArray(p.certificates) ? p.certificates[0] : null;
const loads = Array.isArray(p.contacted_domains) ? p.contacted_domains : [];

const domainBody = d.status === 'ok'
  ? `${esc(d.registrable_domain)} &middot; registered ${esc((d.registered_at || '?').slice(0, 10))} (${esc(d.age_days ?? '?')} days ago)` +
    `${d.registrar ? ` &middot; ${esc(d.registrar)}` : ''}${d.shared_platform ? '<br>Shared platform: registration describes the platform, not the owner.' : ''}`
  : `RDAP: ${esc(d.status)}`;
const certBody = c.status === 'ok'
  ? `${esc(c.count)} certificate(s), first ${esc((c.first_seen || '?').slice(0, 10))}, latest ${esc((c.latest || '?').slice(0, 10))} &middot; ${esc(c.names_seen)} name(s)`
  : `crt.sh: ${esc(c.status)}`;
const pageBody = p.status === 'scanned'
  ? `${esc(r.page_type || 'unknown')}${r.impersonated_brand ? ` &middot; pretends to be <strong>${esc(r.impersonated_brand)}</strong>` : ''}` +
    `${r.credential_harvesting ? ' &middot; <span style="color:#ff5252;">asks for credentials</span>' : ''}` +
    `<br>Title: ${esc(p.title || 'none')} &middot; HTTP ${esc(p.http_status ?? '?')}<br>Final URL: <span style="font-family:monospace;">${esc(p.final_url || '?')}</span>` +
    (pc ? `<br>TLS certificate: ${esc(pc.subject)} &middot; ${esc(pc.issuer || '?')} &middot; from ${esc((pc.valid_from || '?').slice(0, 10))}${pc.age_days !== null && pc.age_days <= 30 ? ` <span style="color:#ff5252;">(${esc(pc.age_days)} day(s) ago)</span>` : ''}` : '') +
    (loads.length ? `<br>Loads resources from: ${esc(loads.slice(0, 10).join(', '))}${loads.length > 10 ? ` +${esc(loads.length - 10)} more` : ''}` : '') +
    `<br>${[link(r.report_url, 'urlscan.io report'), link(r.screenshot_url, 'screenshot')].filter(Boolean).join(' &middot; ')}`
  : `Page not scanned: ${esc(p.status)}${p.message ? ` &middot; ${esc(p.message)}` : ''}`;
const si = f.same_ip_sites;
const relatedBody = si?.status === 'ok'
  ? `${esc(si.other_sites)} other site(s) on the IP${si.malicious_sites ? `, <span style="color:#ff5252;">${esc(si.malicious_sites)} malicious</span>` : ''}: ` +
    si.sites.slice(0, 10).map((x) => `${esc(x.domain)}${x.malicious ? ' <span style="color:#ff5252;">(malicious)</span>' : ''}`).join(', ') +
    (si.other_sites > 10 ? ` +${esc(si.other_sites - 10)} more` : '')
  : '';

const html = `<!DOCTYPE html><html><body style="margin:0;padding:20px;background:#121212;font-family:Arial,sans-serif;color:#e0e0e0;">
<div style="max-width:640px;margin:0 auto;background:#1e1e1e;border-top:4px solid ${theme.accent};border-radius:8px;overflow:hidden;">
  <div style="background:${theme.header};padding:15px;text-align:center;">
    <h2 style="margin:0;color:${theme.text};">${theme.label}: Cyber Sentinel Deep Recon</h2>
  </div>
  <div style="padding:24px;">
    <div style="background:#2d2d2d;border:1px solid #444;border-radius:5px;padding:10px;text-align:center;margin-bottom:18px;">
      <div style="font-size:12px;color:#888;text-transform:uppercase;letter-spacing:1px;">Verdict &rarr; Deep Recon</div>
      <div style="font-size:36px;font-weight:bold;color:${theme.text};">${esc(r.original_score)}/5 &rarr; ${esc(r.proposed_score)}/5</div>
      <div style="font-size:12px;color:#aaa;text-transform:uppercase;">${esc(level.description)} &middot; ${esc(level.action)}</div>
      <div style="font-size:12px;color:#bbb;margin-top:6px;">${esc(r.score_reason)}</div>
    </div>
    <p><strong>Domena:</strong> <span style="color:#90caf9;">${esc(r.fqdn)}</span></p>
    <p><strong>Ocena strony:</strong> ${esc(r.supports_verdict)} (${esc(r.confidence)})</p>
    <p style="color:#ffd54f;">Werdykt w bazie nie został zmieniony - to propozycja do decyzji.</p>
    ${box('Analiza (PL)', esc(r.analysis_pl))}
    ${box('Summary (EN)', esc(r.summary_en))}
    ${box('Page', pageBody)}
    ${box('Domain', domainBody)}
    ${box('Certificates', certBody)}
    ${box('Same IP (urlscan.io)', relatedBody)}
    ${r.indicators && r.indicators.length ? box('Indicators', `<ul style="margin:0;padding-left:18px;">${r.indicators.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>`) : ''}
  </div>
  <div style="text-align:center;font-size:11px;color:#777;padding:12px;">
    Cyber Sentinel Deep Recon &middot; recon #${esc(r.recon_id)} &middot; analysis #${esc(r.analysis_result_id)} &middot; prompt ${esc(r.prompt_version)}
  </div>
</div></body></html>`;

return {
  json: {
    subject: `Cyber Sentinel Deep Recon ${r.original_score}/5 → ${r.proposed_score}/5 | ${r.fqdn}`,
    html,
  },
};
